{
  "aggregate": "question",
  "pipeline": {{
  (() => {
    const targetDomain = this.params.domain || "";
    const limitCount = Number(this.params.questionLimit) || 10;
    const isWeighted = Switch2.isSwitchedOn;
    const priorityLimit = Number(this.params.minOccure) || 0;
    let pipeline = [
      {
        "$match": {
          "domain": targetDomain
        }
      }
    ];

    if (!isWeighted) {
      // MODUS 1: Gewichtung AUS -> Reine Zufallsauswahl
      pipeline.push(
        { "$sample": { "size": limitCount } }
      );
    } else {
      // MODUS 2: Gewichtung EIN -> Usage Count ermitteln und priorisieren
      pipeline.push(
        {
          "$lookup": {
            "from": "appsmith_test",
            "let": { "qIdStr": { "$toString": "$_id" } },
            "pipeline": [
              { "$unwind": "$questions" },
              {
                "$match": {
                  "$expr": { "$eq": ["$questions._id", "$$qIdStr"] }
                }
              },
              { "$count": "occurrenceCount" }
            ],
            "as": "testCountData"
          }
        },
        {
          "$addFields": {
            "usageCount": {
              "$ifNull": [{ "$arrayElemAt": ["$testCountData.occurrenceCount", 0] }, 0]
            },
            "randomOrder": { "$rand": {} }
          }
        },
        {
          "$project": {
            "testCountData": 0
          }
        },
        {
          "$match": {
            "usageCount": { "$lte": priorityLimit }
          }
        },
        {
          "$sort": {
            "usageCount": 1,
            "randomOrder": 1
          }
        },
        {
          "$limit": limitCount
        }
      );
    }

    // Antworten anhängen
    pipeline.push(
      {
        "$lookup": {
          "from": "answer",
          "localField": "_id",
          "foreignField": "question_id",
          "as": "answers"
        }
      }
    );

    return pipeline;
  })()
}},
  "cursor": {
  "batchSize": {{ Number(this.params.questionLimit) || 10 }}
}
}
